/**
 * generated by stackra gen from src/config/desktop.config.ts, src/config/csp.config.ts,
 * src/config/peripherals.config.ts, src/config/env.config.ts, runway.yaml
 * (environments.dev.desktop, release.desktop.feedPath, environments.<env>.desktop.channel), root
 * runway.yaml (feed.publicOrigin) and desktop/wiring.ts — do not edit
 * Purpose: the Electron main-process entry: single instance (a second launch hands its arguments to
 *          the first and exits before it registers anything), the privileged `app://` scheme, then
 *          the platform's desktop app with the main-process wiring, the generated bridge handlers,
 *          the `@Menu` classes and the hardening baseline.
 * Boundary: the baseline is not configurable (context isolation, sandbox, no node integration, web
 *           security, no webview, the CSP header, navigation and window-open guards, permission
 *           handlers, fuses; ADR 0251 d3). Config classes are resolved from the container, never
 *           read as statics. The update feed is derived here from the root feed origin, the
 *           member's feed path and the environment's channel.
 * Runtime: node
 */
import { app, protocol } from "electron";
import { createDesktopApp } from "@stackra/platform/electron";
import { devPorts, updateFeed } from "@stackra/runway/ports";
import { AppMenu } from "#src/menus/app.menu";
import { ContextMenu } from "#src/menus/context.menu";
import { TrayMenu } from "#src/menus/tray.menu";
import { handlerTable } from "./handlers";
import { mainWiring } from "./wiring";

/** Boots main once; a second instance quits and stops here, so it never races the first. */
async function start(): Promise<void> {
  if (!app.requestSingleInstanceLock()) {
    app.quit(); // the first instance receives this launch's argv through `second-instance`
    return;
  }
  protocol.registerSchemesAsPrivileged([
    { scheme: "app", privileges: { standard: true, secure: true, supportFetchAPI: true } },
  ]); // never bypassCSP

  /**
   * `null` when packaged; in dev the member runway's port, remote-debug and PKCE loopback ports
   * via ports.json.
   */
  const dev = app.isPackaged ? null : devPorts("console");

  await createDesktopApp({
    key: "console",
    wiring: mainWiring, // main-process drivers only: bridges, peripherals, file system
    // the generated IPC table (allow-list, schema, actors, permission); the dev origin when unpackaged
    handlers: handlerTable(dev && new URL(dev.url).origin),
    menus: { application: AppMenu, tray: TrayMenu, context: ContextMenu },
    rendererDir: new URL("../renderer/", import.meta.url), // served as app://bundle/
    preload: new URL("./preload.cjs", import.meta.url),
    dev: dev && { url: dev.url, ...dev.desktop },
    updateFeed: updateFeed("console"), // <feed.publicOrigin>/<release.desktop.feedPath>/<channel>/
  });
}

await start();
